describe('Pagination Controls', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="results-container"]').should('be.visible');
  });

  it('should load the correct page when clicking next button', () => {
    cy.get('[data-testid="pagination-next"]').should('be.enabled');
    cy.get('[data-testid="result-item"]').should('have.length', 10);
    cy.get('[data-testid="result-item"]').first().should('contain', 'Item 1');

    cy.get('[data-testid="pagination-next"]').click();
    cy.get('[data-testid="current-page"]').should('contain', '2');
    cy.get('[data-testid="result-item"]').should('have.length', 10);
    cy.get('[data-testid="result-item"]').first().should('contain', 'Item 11');
  });

  it('should load the correct page when clicking previous button', () => {
    cy.get('[data-testid="pagination-next"]').click();
    cy.get('[data-testid="current-page"]').should('contain', '2');

    cy.get('[data-testid="pagination-prev"]').should('be.enabled');
    cy.get('[data-testid="pagination-prev"]').click();
    cy.get('[data-testid="current-page"]').should('contain', '1');
    cy.get('[data-testid="result-item"]').first().should('contain', 'Item 1');
  });

  it('should load the correct page when clicking a specific page number', () => {
    cy.get('[data-testid="pagination-page-3"]').should('be.visible');
    cy.get('[data-testid="pagination-page-3"]').click();
    cy.get('[data-testid="current-page"]').should('contain', '3');
    cy.get('[data-testid="result-item"]').should('have.length', 10);
    cy.get('[data-testid="result-item"]').first().should('contain', 'Item 21');
  });

  it('should disable previous button on first page', () => {
    cy.get('[data-testid="current-page"]').should('contain', '1');
    cy.get('[data-testid="pagination-prev"]').should('be.disabled');
  });

  it('should disable next button on last page', () => {
    cy.get('[data-testid="pagination-last-page"]').then(($lastPage) => {
      const lastPageNum = $lastPage.text();
      cy.get(`[data-testid="pagination-page-${lastPageNum}"]`).click();
      cy.get('[data-testid="pagination-next"]').should('be.disabled');
    });
  });

  it('should maintain filters when navigating between pages', () => {
    cy.get('[data-testid="filter-category"]').select('Electronics');
    cy.get('[data-testid="apply-filters"]').click();
    cy.get('[data-testid="result-item"]').should('have.length', 10);

    cy.get('[data-testid="pagination-next"]').click();
    cy.get('[data-testid="filter-category"]').should('have.value', 'Electronics');
    cy.get('[data-testid="result-item"]').each(($item) => {
      cy.wrap($item).should('contain', 'Electronics');
    });
  });

  it('should handle rapid pagination clicks without errors', () => {
    cy.get('[data-testid="pagination-next"]').click();
    cy.get('[data-testid="pagination-next"]').click();
    cy.get('[data-testid="pagination-prev"]').click();
    cy.get('[data-testid="current-page"]').should('contain', '2');
    cy.get('[data-testid="result-item"]').should('have.length', 10);
    cy.get('[data-testid="results-error"]').should('not.exist');
  });

  it('should update URL when navigating pages', () => {
    cy.get('[data-testid="pagination-next"]').click();
    cy.url().should('include', 'page=2');

    cy.get('[data-testid="pagination-page-5"]').click();
    cy.url().should('include', 'page=5');
  });

  it('should handle empty results on a page gracefully', () => {
    cy.get('[data-testid="filter-search"]').type('nonexistentitem');
    cy.get('[data-testid="apply-filters"]').click();
    cy.get('[data-testid="no-results-message"]').should('be.visible');
    cy.get('[data-testid="pagination-controls"]').should('not.exist');
  });

  it('should display correct page info text', () => {
    cy.get('[data-testid="pagination-info"]').should('contain', 'Showing 1-10 of');

    cy.get('[data-testid="pagination-next"]').click();
    cy.get('[data-testid="pagination-info"]').should('contain', 'Showing 11-20 of');
  });
});
